package com.smarthospital.controller;
import com.smarthospital.model.User;import com.smarthospital.service.PhpBridge;import com.smarthospital.util.*;import javax.servlet.*;import javax.servlet.annotation.*;import javax.servlet.http.*;import java.io.*;import java.sql.*;import java.util.*;
@WebServlet("/my-duties") public class MyDutiesServlet extends HttpServlet{
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{User u=(User)req.getSession().getAttribute("user");try(Connection c=DB.getConnection()){List<Map<String,Object>>l=new ArrayList<>();String q="SELECT da.assignment_id,d.duty_id,d.duty_name,d.duty_date,d.start_time,d.end_time,d.priority,da.status,COALESCE((SELECT verification_status FROM documents doc WHERE doc.duty_id=d.duty_id AND doc.staff_id=da.staff_id ORDER BY doc.uploaded_at DESC LIMIT 1),'NOT_UPLOADED'),COALESCE((SELECT cr.status FROM duty_change_requests cr WHERE cr.assignment_id=da.assignment_id ORDER BY cr.created_at DESC LIMIT 1),'NONE'),COALESCE((SELECT cr.reason FROM duty_change_requests cr WHERE cr.assignment_id=da.assignment_id ORDER BY cr.created_at DESC LIMIT 1),'') FROM duty_assignments da JOIN duties d ON da.duty_id=d.duty_id JOIN staff s ON da.staff_id=s.staff_id WHERE s.user_id=? ORDER BY CASE WHEN d.duty_date>=CURDATE() THEN 0 ELSE 1 END,d.duty_date ASC,d.start_time ASC";try(PreparedStatement p=c.prepareStatement(q)){p.setInt(1,u.id());try(ResultSet r=p.executeQuery()){while(r.next()){Map<String,Object>m=new HashMap<>();for(int i=1;i<=11;i++)m.put("c"+i,r.getObject(i));l.add(m);}}}req.setAttribute("rows",l);req.getRequestDispatcher("/my-duties.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{User u=(User)req.getSession().getAttribute("user");String action=req.getParameter("action");try(Connection c=DB.getConnection()){int id=Integer.parseInt(req.getParameter("assignment_id"));if("change".equals(action)){String reason=req.getParameter("reason");if(reason==null||reason.trim().length()<5)throw new IllegalArgumentException("Please provide a change reason of at least 5 characters.");if(reason.trim().length()>1000)throw new IllegalArgumentException("Change reason is too long.");c.setAutoCommit(false);int staffId;String dutyName,deptName,email,name;String prev;try(PreparedStatement p=c.prepareStatement("SELECT da.staff_id,d.duty_name,dp.department_name,COALESCE(s.email,''),s.name,da.status FROM duty_assignments da JOIN duties d ON da.duty_id=d.duty_id JOIN departments dp ON d.department_id=dp.department_id JOIN staff s ON da.staff_id=s.staff_id WHERE da.assignment_id=? AND s.user_id=? AND da.status IN ('ASSIGNED','ACKNOWLEDGED')")){p.setInt(1,id);p.setInt(2,u.id());try(ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Duty cannot accept a change request in its current state.");staffId=r.getInt(1);dutyName=r.getString(2);deptName=r.getString(3);email=r.getString(4);name=r.getString(5);prev=r.getString(6);}}
 int pending=0;try(PreparedStatement p=c.prepareStatement("SELECT COUNT(*) FROM duty_change_requests WHERE assignment_id=? AND status='PENDING'")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){r.next();pending=r.getInt(1);}}if(pending>0)throw new IllegalArgumentException("A change request is already pending for this duty.");
 try(PreparedStatement p=c.prepareStatement("INSERT INTO duty_change_requests(assignment_id,staff_id,reason,previous_assignment_status) VALUES(?,?,?,?)")){p.setInt(1,id);p.setInt(2,staffId);p.setString(3,reason.trim());p.setString(4,prev);p.executeUpdate();}
 try(PreparedStatement p=c.prepareStatement("UPDATE duty_assignments SET status='CHANGE_REQUESTED' WHERE assignment_id=?")){p.setInt(1,id);p.executeUpdate();}
 try(PreparedStatement p=c.prepareStatement("SELECT u.user_id,u.full_name,COALESCE(u.email,'') FROM users u JOIN supervisor_departments sd ON u.user_id=sd.supervisor_user_id WHERE u.role='SUPERVISOR' AND u.status='ACTIVE' AND sd.active=1 AND sd.department_id=(SELECT department_id FROM duties d JOIN duty_assignments da ON d.duty_id=da.duty_id WHERE da.assignment_id=?)")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){while(r.next()){int uid=r.getInt(1);String sn=r.getString(2),se=r.getString(3);try(PreparedStatement n=c.prepareStatement("INSERT INTO notifications(user_id,message,type) VALUES(?,?,?)")){n.setInt(1,uid);n.setString(2,name+" requested a change for '"+dutyName+"' ("+deptName+"). Reason: "+reason.trim());n.setString(3,"CHANGE_REQUEST");n.executeUpdate();}if(se!=null&&!se.isBlank())PhpBridge.sendDutyMail(se,sn,name+" requested a duty change for '"+dutyName+"'. Reason: "+reason.trim());}}}
 c.commit();Audit.log(u.id(),"CHANGE_REQUEST","Requested change for assignment #"+id);resp.sendRedirect(req.getContextPath()+"/my-duties");return;}
 String st=null;
 if("acknowledge".equals(action)) st="ACKNOWLEDGED";
 else if("start".equals(action)) st="IN_PROGRESS";
 else if("complete".equals(action)){
   c.setAutoCommit(false);
   int staffId; String dutyName, deptName;
   try(PreparedStatement p=c.prepareStatement("SELECT da.staff_id,d.duty_name,dp.department_name FROM duty_assignments da JOIN duties d ON da.duty_id=d.duty_id JOIN departments dp ON d.department_id=dp.department_id JOIN staff s ON da.staff_id=s.staff_id WHERE da.assignment_id=? AND s.user_id=? AND da.status='IN_PROGRESS'")){
     p.setInt(1,id); p.setInt(2,u.id());
     try(ResultSet r=p.executeQuery()){ if(!r.next()) throw new IllegalArgumentException("Only an in-progress duty can be marked completed."); staffId=r.getInt(1); dutyName=r.getString(2); deptName=r.getString(3); }
   }
   try(PreparedStatement p=c.prepareStatement("UPDATE duty_assignments SET status='COMPLETION_PENDING' WHERE assignment_id=? AND staff_id=? AND status='IN_PROGRESS'")){ p.setInt(1,id); p.setInt(2,staffId); if(p.executeUpdate()==0) throw new IllegalArgumentException("Duty cannot be completed in its current state."); }
   try(PreparedStatement n=c.prepareStatement("INSERT INTO notifications(user_id,message,type) SELECT u.user_id,?,'COMPLETION_SUBMITTED' FROM users u JOIN supervisor_departments sd ON u.user_id=sd.supervisor_user_id WHERE u.role='SUPERVISOR' AND u.status='ACTIVE' AND sd.active=1 AND sd.department_id=(SELECT department_id FROM duties WHERE duty_id=(SELECT duty_id FROM duty_assignments WHERE assignment_id=?)) UNION ALL SELECT u.user_id,?,'COMPLETION_SUBMITTED' FROM users u WHERE u.role='ADMIN' AND u.status='ACTIVE'")){
     String msg="Staff marked duty '"+dutyName+"' as completed. Please review the work proof for "+deptName+".";
     n.setString(1,msg); n.setInt(2,id); n.setString(3,msg); n.executeUpdate();
   }
   Audit.log(u.id(),"DUTY_COMPLETION_SUBMITTED","Assignment #"+id+" marked completion pending");
   c.commit(); resp.sendRedirect(req.getContextPath()+"/my-duties"); return;
 }
 if(st==null)throw new IllegalArgumentException("Unsupported duty action.");
 try(PreparedStatement p=c.prepareStatement("UPDATE duty_assignments SET status=? WHERE assignment_id=? AND staff_id=(SELECT staff_id FROM staff WHERE user_id=?) AND status IN ('ASSIGNED','ACKNOWLEDGED')")){p.setString(1,st);p.setInt(2,id);p.setInt(3,u.id());if(p.executeUpdate()==0)throw new IllegalArgumentException("Duty cannot be changed in its current state.");}
 Audit.log(u.id(),"DUTY_STATUS",st+" assignment #"+id);resp.sendRedirect(req.getContextPath()+"/my-duties");}catch(Exception e){resp.sendError(400,e.getMessage());}}
}
